module protocol::user_rebates;

use std::string::String;
use std::type_name::{Self, TypeName};

use sui::random::Random;
use sui::event::emit;

use protocol::app::ProtocolApp;

public struct ReferralCodeGeneratedEvent has drop, copy {
    app: ID,
    who: address,
    code: String,
}

public struct ReferralRebateClaimedEvent has drop, copy {
    app: ID,
    who: address,

    rebate_amount: u64,
    rebate_coin: TypeName,
}

public fun can_generate_referral_code(self: &ProtocolApp, who: address): bool { self.referral().is_qualified_to_create_referral_code(who) }

public fun has_referral_code(self: &ProtocolApp, who: address): bool { self.referral().has_referral_code(who) }

public fun get_referral_code(self: &ProtocolApp, who: address): String { self.referral().get_referral_code(who) }

public fun get_linked_code(self: &ProtocolApp, who: address): Option<String> { self.referral().get_linked_referral_code(who) }

public fun get_referral_rebates(self: &ProtocolApp, who: address): (vector<TypeName>, vector<u64>) { self.referral().list_rebates(who) }

// writer function
entry fun generate_referral_code(self: &mut ProtocolApp, rand: &Random, ctx: &mut TxContext) { generate_referral_code_inner(self, rand, ctx) }

#[allow(lint(self_transfer))]
public fun claim_referral_rebates<CoinType>(self: &mut ProtocolApp, ctx: &mut TxContext) {
    self.ensure_version_matches();

    let coin = self.referral_mut().claim_rebates<CoinType>(ctx);

    emit(ReferralRebateClaimedEvent{
        app: object::id(self),
        who: ctx.sender(),
        rebate_amount: coin.value(),
        rebate_coin: type_name::with_defining_ids<CoinType>(),
    });

    transfer::public_transfer(coin, ctx.sender());
}

// internal functions
fun generate_referral_code_inner(self: &mut ProtocolApp, rand: &Random, ctx: &mut TxContext) {
    self.ensure_version_matches();

    let referral = self.referral_mut();

    referral.generate_referral_code(rand, ctx);

    let code = referral.get_referral_code(ctx.sender());

    emit(ReferralCodeGeneratedEvent {
        app: object::id(self),
        who: ctx.sender(),
        code,
    });
}

