module protocol::liquidity_mining_admin;

use std::type_name;

use sui::clock::Clock;
use sui::coin::Coin;
use sui::event::emit;

use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;

// === Events ===
public struct LiquidityMiningRewardAddedEvent has copy, drop {
    market: ID,
    coin_type: std::type_name::TypeName,
    reward_coin_type: std::type_name::TypeName,
    reward_type: u8,
    amount: u64,
    start_time_ms: u64,
    end_time_ms: u64,
}

public struct LiquidityMiningRewardCancelledEvent has copy, drop {
    market: ID,
    coin_type: std::type_name::TypeName,
    reward_coin_type: std::type_name::TypeName,
    reward_type: u8,
    reward_index: u64,
    refunded_amount: u64,
}

public struct LiquidityMiningRewardClosedEvent has copy, drop {
    market: ID,
    coin_type: std::type_name::TypeName,
    reward_coin_type: std::type_name::TypeName,
    reward_type: u8,
    reward_index: u64,
    refunded_amount: u64,
}

// === Public Functions ===
public fun add_liquidity_mining_rewards<MarketType, CoinType, RewardCoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    reward_type: u8,
    rewards: Coin<RewardCoinType>,
    start_time_ms: u64,
    end_time_ms: u64,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    // sanity check
    assert!(rewards.value() != 0, protocol::error::invalid_params_error());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let amount = rewards.value();
    let liquidity_miner = market.borrow_liquidity_mining_mut();

    liquidity_miner.add_reward<MarketType, CoinType, RewardCoinType>(
        reward_type,
        rewards,
        start_time_ms,
        end_time_ms,
        clock,
        ctx
    );

    emit(LiquidityMiningRewardAddedEvent {
        market: object::id(market),
        coin_type: type_name::with_defining_ids<CoinType>(),
        reward_coin_type: type_name::with_defining_ids<RewardCoinType>(),
        reward_type,
        amount,
        start_time_ms,
        end_time_ms,
    });
}

#[allow(lint(self_transfer))]
public fun cancel_liquidity_mining_rewards<MarketType, CoinType, RewardCoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    reward_type: u8,
    reward_index: u64,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let liquidity_miner = market.borrow_liquidity_mining_mut();

    let balance = liquidity_miner.cancel_reward<MarketType, CoinType, RewardCoinType>(
        reward_type,
        reward_index,
        clock
    );

    let refunded_amount = balance.value();
    let refund_coin = balance.into_coin(ctx);

    emit(LiquidityMiningRewardCancelledEvent {
        market: object::id(market),
        coin_type: type_name::with_defining_ids<CoinType>(),
        reward_coin_type: type_name::with_defining_ids<RewardCoinType>(),
        reward_type,
        reward_index,
        refunded_amount,
    });

    // Transfer refund to sender
    transfer::public_transfer(refund_coin, ctx.sender());
}

#[allow(lint(self_transfer))]
public fun close_liquidity_mining_rewards<MarketType, CoinType, RewardCoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    reward_type: u8,
    reward_index: u64,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let liquidity_miner = market.borrow_liquidity_mining_mut();

    let balance = liquidity_miner.close_reward<MarketType, CoinType, RewardCoinType>(
        reward_type,
        reward_index,
        clock
    );

    let refunded_amount = balance.value();
    let refund_coin = balance.into_coin(ctx);

    emit(LiquidityMiningRewardClosedEvent {
        market: object::id(market),
        coin_type: type_name::with_defining_ids<CoinType>(),
        reward_coin_type: type_name::with_defining_ids<RewardCoinType>(),
        reward_type,
        reward_index,
        refunded_amount,
    });

    // Transfer refund to sender
    transfer::public_transfer(refund_coin, ctx.sender());
}

module protocol::emode_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::limiter::NewLimiter;
use protocol::emode::{new_emode_params, NewEMode};

const EMODE_CREATED: u8 = 0;
const EMODE_UPDATED: u8 = 1;

const BPS_DENOMINATOR: u64 = 10000;

public struct NewEModeGroupEvent has copy, drop {
    market: TypeName,
    emode_group_id: u8,
    oracle_base_token: u8,
    time: u64,
    operator: address,
}

public struct EModeUpdated<T> has copy, drop {
    who: address,
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun create_limiter(
    _: &AdminCap,
    self: &ProtocolApp,
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
): protocol::limiter::NewLimiter {
    self.ensure_version_matches();

    protocol::limiter::create_new_limiter_change(outflow_limit, outflow_cycle_duration, outflow_segment_duration)
}

public fun onboard_new_emode_group<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    oracle_base_token: u8,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let id = market.emode_registry_mut().new_emode_group(oracle_base_token, ctx);
    let now = clock.timestamp_ms() / 1000;

    emit(NewEModeGroupEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        emode_group_id: id,
        oracle_base_token,
        time: now,
        operator: ctx.sender(),
    });
}

public fun create_emode_params(
    cap: &AdminCap,
    self: &ProtocolApp,

    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < liquidation_factor_bps, error::invalid_params_error());
    assert!(liquidation_factor_bps - collateral_factor_bps < liquidation_incentive_bps, error::invalid_params_error());

    self.ensure_version_matches();

    // liquidation factor * (1 + liquidation incentive) < 1
    assert!(
        liquidation_factor_bps * (BPS_DENOMINATOR + liquidation_incentive_bps) / BPS_DENOMINATOR < BPS_DENOMINATOR,
        error::invalid_params_error()
    );

    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

public fun onboard_asset_to_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.emode_registry_mut().support_asset<CoinType>(group, params, ctx);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_CREATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        who: ctx.sender(),
        new: params
    });
}

public fun update_asset_in_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let asset = std::type_name::with_defining_ids<CoinType>();
    let emode = market.emode_registry_mut().borrow_mut_emode(group, asset);
    emode.update(params);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_UPDATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset,
        who: ctx.sender(),
        new: params
    });
}

fun create_emode_params_inner(
    _: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_incentive_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(borrow_weight_bps >= BPS_DENOMINATOR, error::invalid_params_error());
    assert!(flash_loan_fee_rate_bps < BPS_DENOMINATOR, error::invalid_params_error());

    let collateral_factor = math::float::from_quotient(collateral_factor_bps, BPS_DENOMINATOR);
    let liquidation_factor = math::float::from_quotient(liquidation_factor_bps, BPS_DENOMINATOR);
    let liquidation_incentive = math::float::from_quotient(liquidation_incentive_bps, BPS_DENOMINATOR);
    let borrow_weight = math::float::from_quotient(borrow_weight_bps, BPS_DENOMINATOR);
    let flash_loan_fee_rate = math::float::from_quotient(flash_loan_fee_rate_bps, BPS_DENOMINATOR);

    new_emode_params(
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,
        max_borrow_amount,
        borrow_weight,
        flash_loan_fee_rate,
        deposit_limiter,
        borrow_limiter,
    )
}

#[test_only]
public fun create_emode_params_test(
    cap: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

module protocol::referral_admin;

use sui::clock::{Self, Clock};
use sui::event::emit;

use protocol::app::{AdminCap, ProtocolApp};


/// Event emitted when revenue is taken from a market
public struct ReferralUpdatedEvent has copy, drop {
    app: ID,

    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,

    sender: address,
    timestamp_ms: u64,
}

public struct ReferralClaimPauseUpdatedEvent has copy, drop {
    app: ID,

    is_pause: bool,

    sender: address,
    timestamp_ms: u64,
}

/// Take accumulated revenue from a market
public fun update_referral_params(
    _: &AdminCap,
    app: &mut ProtocolApp,

    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,

    clock: &Clock,
    ctx: &TxContext,
) {
    app.ensure_version_matches();

    app
