module protocol::revenue_admin;

use std::type_name::{Self, TypeName};

use sui::clock::{Self, Clock};
use sui::event;

use protocol::error;
use protocol::market::{Self, Market};
use protocol::app::{AdminCap, ProtocolApp};


/// Event emitted when revenue is taken from a market
public struct TakeRevenueEvent has copy, drop {
    market: ID,
    amount: u64,
    coin_type: TypeName,
    sender: address,
    timestamp_ms: u64,
}

/// Take accumulated revenue from a market
public fun take_revenue<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    amount: u64,
    recipient: address,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(amount > 0, error::invalid_params_error());

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    event::emit(TakeRevenueEvent {
        market: object::id(market),
        amount,
        coin_type: type_name::with_defining_ids<CoinType>(),
        sender: ctx.sender(),
        timestamp_ms: clock::timestamp_ms(clock),
    });

    let coin = market::take_revenue<MarketType, CoinType>(market, amount, ctx);
    transfer::public_transfer(coin, recipient);
}

