module protocol::decimals_admin;

use std::type_name::{Self, TypeName};
use sui::event::emit;
use sui::coin::CoinMetadata;

use protocol::coin_decimals_registry::{Self, CoinDecimalsRegistry};
use protocol::app::ProtocolApp;

public struct CoinDecimalsRegistered has copy, drop {
    registry: ID,
    coin_type: TypeName,
    decimals: u8,
}

// Since coinMeta is 1:1 for a coin,
// CoinMeta is the single source of truth for the coin
// Anyone can add the registry
public fun register_decimals<T>(
    _: &protocol::app::AdminCap,
    app: &ProtocolApp,
    registry: &mut CoinDecimalsRegistry,
    coin_meta: &CoinMetadata<T>,
) {
    app.ensure_version_matches();

    let decimals = coin_decimals_registry::register_decimals<T>(registry, coin_meta);

    emit(CoinDecimalsRegistered {
        registry: object::id(registry),
        coin_type: type_name::with_defining_ids<T>(),
        decimals,
    })
}

